const API_KEY = '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';

function brevoPost(payload) {
  return new Promise((resolve, reject) => {
    const body = JSON.stringify(payload);
    const req = https.request({
      hostname: 'api.brevo.com',
      path: '/v3/smtp/email',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'api-key': API_KEY,
        'Content-Length': Buffer.byteLength(body)
      }
    }, res => {
      let data = '';
      res.on('data', d => data += d);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}

exports.handler = async (event) => {
  if (event.httpMethod !== 'POST') return { statusCode: 405, body: 'Method Not Allowed' };

  let name, email;
  try {
    const params = new URLSearchParams(event.body);
    name  = params.get('name')  || '';
    email = params.get('email') || '';
  } catch(e) {
    return { statusCode: 400, body: 'Bad request' };
  }

  if (!email) return { statusCode: 400, body: 'Email required' };

  await Promise.all([
    brevoPost({
      sender: { name: 'rho interior', email: 'design@rhointerior.com' },
      to: [{ email, name }],
      replyTo: { email: 'design@rhointerior.com' },
      subject: 'You’re on the list',
      htmlContent: HTML_CONTENT
    }),
    brevoPost({
      sender: { name: 'rho interior', email: 'design@rhointerior.com' },
      to: [{ email: 'design@rhointerior.com' }],
      subject: 'New sign-up: ' + name,
      htmlContent: '<p>Name: ' + name + '</p><p>Email: ' + email + '</p>'
    })
  ]);

  return { statusCode: 200, body: 'ok' };
};
